func stressViewPayload(t *testing.T) app.InventoryPayload {
	t.Helper()
	var p app.InventoryPayload
	if json.Unmarshal([]byte(stressReportLiteral), &p) != nil {
		t.Fatal("literal report")
	}
	if err := app.ValidateCoverage(p); err != nil {
		t.Fatal("valid view prerequisite", err)
	}
	return p
}

func TestCPUStressViewsUseValidatedFiniteWindowAndStandardScope(t *testing.T) {
	p := stressViewPayload(t)
	html, err := InventoryHTMLForVersion(p, "0.0.1-fixture")
	if err != nil {
		t.Fatal(err)
	}
	pdf, err := InventoryPDFForVersion(p, "0.0.1-fixture")
	if err != nil {
		t.Fatal(err)
	}
	for _, label := range []string{"CPU STRESS (STANDARD PROFILE)", "Requested load (ms)", "Observed load window (ms)", "Ready workers", "Load scalar checks", "Cleanup confirmed"} {
		if !bytes.Contains(html, []byte(label)) {
			t.Fatal("missing literal HTML label", label)
		}
	}
	if !bytes.Contains(html, []byte("Workload counters do not measure CPU time or utilization.")) || !bytes.Contains(html, []byte("Standard-session execution, cleanup")) {
		t.Fatal("truthful standard scope missing")
	}
	lines, err := inventoryPDFLines(p, "0.0.1-fixture")
	if err != nil {
		t.Fatal(err)
	}
	joined := strings.Join(lines, " ")
	for _, label := range []string{"CPU STRESS (STANDARD PROFILE)", "Requested load (ms): 600000", "Observed load window (ms): 600000", "Ready workers: 1/1", "Load scalar checks: 12", "Cleanup confirmed: true", "load iterations 255"} {
		if !strings.Contains(joined, label) {
			t.Fatal("missing literal PDF field", label)
		}
	}
	if len(pdf) == 0 {
		t.Fatal("empty PDF")
	}
	doc, err := cpuStressReportDocument(p)
	if err != nil || doc == nil || len(doc.Workers) != 1 || doc.Workers[0].Entry != "2" || doc.Workers[0].Stop != 600002 || doc.Workers[0].Reason != "completed" {
		t.Fatal("ordered worker view", err)
	}
}

func TestCPUStressViewsRejectBeforeWritingAndPreserveAbsentGoldens(t *testing.T) {
	stressViewPayload(t)
	for _, name := range []string{"opaque", "cleanup", "unknown_schema"} {
		t.Run(name, func(t *testing.T) {
			changed := stressViewPayload(t)
			switch name {
			case "opaque":
				changed.TestResults[1].Evidence = []byte(`{}`)
			case "cleanup":
				changed.TestResults[1].Evidence = bytes.Replace(changed.TestResults[1].Evidence, []byte(`"cleanup_confirmed":true`), []byte(`"cleanup_confirmed":false`), 1)
			case "unknown_schema":
				changed.TestResults[1].Evidence = bytes.Replace(changed.TestResults[1].Evidence, []byte("cpu-stress/v1"), []byte("cpu-stress/v9"), 1)
			}
			if _, err := InventoryHTML(changed); err == nil {
				t.Fatal("invalid HTML stress")
			}
			if _, err := InventoryPDF(changed); err == nil {
				t.Fatal("invalid PDF stress")
			}
			var out bytes.Buffer
			if err := renderInventoryHTMLWithPrevious(&out, changed, "0.0.1-fixture", nil); err == nil || out.Len() != 0 {
				t.Fatal("HTML emitted before validation")
			}
		})
	}
	legacy := app.InventoryPayload{SchemaVersion: 1}
	for _, test := range []struct {
		name, digest string
		size         int
		render       func(app.InventoryPayload, string) ([]byte, error)
	}{
		{"html", "b1930fbb47706d5326913cc470b7bc4746c477b894bf7288ddb677f2b70de775", 3013, InventoryHTMLForVersion},
		{"pdf", "b1582386321add5decc26ff326aa1d84dcb5287436c093dfae68874c1228cf2a", 1166, InventoryPDFForVersion},
	} {
		t.Run(test.name, func(t *testing.T) {
			raw, err := test.render(legacy, "0.0.1-fixture")
			if err != nil || len(raw) != test.size || fmt.Sprintf("%x", sha256.Sum256(raw)) != test.digest {
				t.Fatal("historical absent bytes", err)
			}
		})
	}
}

