func TestCPUStressAdverseViewsKeepMismatchAndIndependentHeat(t *testing.T) {
	var p app.InventoryPayload
	if json.Unmarshal([]byte(stressAdverseReportLiteral), &p) != nil {
		t.Fatal("adverse literal")
	}
	if err := app.ValidateCoverage(p); err != nil {
		t.Fatal("valid adverse prerequisite", err)
	}
	html, err := InventoryHTMLForVersion(p, "0.0.1-fixture")
	if err != nil {
		t.Fatal(err)
	}
	lines, err := inventoryPDFLines(p, "0.0.1-fixture")
	if err != nil {
		t.Fatal(err)
	}
	for _, value := range []string{"calculation_mismatch", "thermal_limit", "90000", "div3", "3d70000000000001"} {
		if !bytes.Contains(html, []byte(value)) || !strings.Contains(strings.Join(lines, " "), value) {
			t.Fatal("independent adverse fact lost", value)
		}
	}
	doc, err := cpuStressReportDocument(p)
	if err != nil || doc == nil || doc.Outcome != "fail" || doc.StopReason != "calculation_mismatch" || doc.Observed != 998 || doc.LoadChecks != 11 {
		t.Fatal("adverse finite summary", err)
	}
}
